$string['studentsubmittedbilan'] = '<p>Bonjour,</p><p><strong>{$a->studentname}</strong>, étudiant(e) que vous tutorez, a soumis le <strong>bilan de son projet personnel</strong> sur la plateforme <strong>ProjetVet</strong>, à l\'issue de la réalisation de l\'activité.</p><p>Nous vous invitons à examiner les éléments renseignés (bilan, justificatifs, volume horaire réellement effectué) afin de :</p><ul><li><strong>échanger</strong> avec l\'étudiant·e sur le déroulement de l\'activité et les compétences mobilisées ;</li><li><strong>valider</strong> le bilan du projet ;</li><li><strong>attribuer</strong> le nombre définitif de crédits <strong>ECTS</strong>, conformément au cadre des crédits de projet personnel (<strong>CPP</strong>).</li></ul><p>L\'ensemble de ces démarches peut être réalisé directement sur la plateforme <strong>ProjetVet</strong>, via le lien ci-dessous :</p><p><i><a href="{$a->link}">Accéder au projet sur ProjetVet</a></i></p><p>Nous vous recommandons vivement de <strong>prendre contact avec l\'étudiant·e</strong> (en présentiel ou à distance) afin d\'échanger sur le bilan, en complément de la validation en ligne.</p><p>Cordialement,<br><i>L\'équipe ProjetVet</i></p>';
$string['studentsubmittedbilan_subject'] = 'Soumission du bilan de projet personnel – validation finale et attribution des ECTS';
$string['studentsubmittedfacetoface'] = '<p>Bonjour,</p><p><strong>{$a->studentname}</strong>, étudiant·e que vous tutorez, a déclaré un <strong>entretien</strong> sur la plateforme <strong>ProjetVet</strong> et a soumis le <strong>compte-rendu associé</strong>.</p><p>Nous vous invitons à <strong>vérifier les informations renseignées</strong> et à confirmer que cet entretien a bien eu lieu, le cas échéant en <strong>validant le compte-rendu</strong>.</p><p>L\'ensemble de ces démarches peut être réalisé directement sur la plateforme <strong>ProjetVet</strong>, via le lien ci-dessous :</p><p><i><a href="{$a->link}">Accéder à l\'entretien sur ProjetVet</a></i></p><p>Nous vous recommandons, si nécessaire, de <strong>prendre contact avec l\'étudiant·e</strong> afin d\'échanger sur le contenu du compte-rendu avant validation.</p><p>Cordialement,<br><strong>L\'équipe ProjetVet</strong></p>';
